		base := unsafe.Add(result, index*(32+4*4))
		utf8 := unsafe.Pointer(unsafe.StringData((element).Topic))
		pinner.Pin(utf8)
		*(*uint32)(unsafe.Add(unsafe.Pointer(base), 4)) = uint32(uint32(len((element).Topic)))
		*(*uint32)(unsafe.Add(unsafe.Pointer(base), 0)) = uint32(uintptr(uintptr(utf8)))
